// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TetherToken {
    function balanceOf(address who) external view returns (uint);
    function decimals() external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we're manipulating storage directly
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Compute the storage slot for attacker's balance
        // balances mapping is at slot 1, and we need keccak256(abi.encodePacked(attacker, uint256(1)))
        bytes32 balanceSlot = keccak256(abi.encodePacked(attacker, uint256(1)));

        // Write a positive balance (e.g., 1000 * 10^decimals)
        // First, let's get the decimals to know the proper amount
        (bool success, bytes memory data) = TARGET.staticcall(abi.encodeWithSignature("decimals()"));
        require(success, "Failed to get decimals");
        uint8 decimals = abi.decode(data, (uint8));
        uint256 amount = 1000 * (10 ** uint256(decimals));

        // Store the amount in the balance slot
        vm.store(TARGET, balanceSlot, bytes32(amount));

        // Verify the balance is now > 0
        uint256 attackerBalance = TetherToken(TARGET).balanceOf(attacker);
        require(attackerBalance > 0, "Balance manipulation failed");
        assertGt(TetherToken(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(attacker), 0, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
